"""
Embedding-cache a Qdrant sync mellé: csak változott payloadra számoljunk új vektort.

Ez a modul egy payload-hash alapú embedding cache-t valósít meg, amely
a Qdrant szinkronizáció során elkerüli a felesleges vektor-újraszámítást.
Csak akkor számol új embeddinget, ha a payload tartalma megváltozott.

Futtatható önálló demo módban: python embedding_cache.py
"""

import hashlib
import json
import os
import sqlite3
import time
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, List, Optional, Tuple

import numpy as np


# ---------------------------------------------------------------------------
# Adatstruktúrák
# ---------------------------------------------------------------------------

@dataclass
class CachedEmbedding:
    """Egy cache-elt embedding és a hozzá tartozó metaadatok."""
    point_id: str
    payload_hash: str
    vector: List[float]
    payload: Dict[str, Any]
    created_at: float
    last_used_at: float
    access_count: int = 0


@dataclass
class SyncResult:
    """A szinkronizáció eredménye."""
    total_points: int = 0
    new_embeddings: int = 0
    cached_embeddings: int = 0
    skipped_unchanged: int = 0
    errors: int = 0
    elapsed_seconds: float = 0.0
    details: List[Dict[str, Any]] = field(default_factory=list)


# ---------------------------------------------------------------------------
# Payload hash számítás
# ---------------------------------------------------------------------------

def compute_payload_hash(payload: Dict[str, Any]) -> str:
    """
    Stabil hash-t számít a payload tartalmából.
    A kulcsokat rendezzük, hogy a sorrend ne befolyásolja a hash-t.
    """
    # JSON serializáció rendezett kulcsokkal
    serialized = json.dumps(
        payload,
        sort_keys=True,
        ensure_ascii=False,
        separators=(",", ":"),
        default=str,
    )
    return hashlib.sha256(serialized.encode("utf-8")).hexdigest()


# ---------------------------------------------------------------------------
# Embedding Cache (SQLite alapú perzisztens tároló)
# ---------------------------------------------------------------------------

class EmbeddingCache:
    """
    SQLite-alapú embedding cache.
    point_id -> (payload_hash, vector, payload, timestamps) leképezést tárol.
    """

    SCHEMA = """
    CREATE TABLE IF NOT EXISTS embedding_cache (
        point_id TEXT PRIMARY KEY,
        payload_hash TEXT NOT NULL,
        vector_json TEXT NOT NULL,
        payload_json TEXT NOT NULL,
        created_at REAL NOT NULL,
        last_used_at REAL NOT NULL,
        access_count INTEGER DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS idx_payload_hash ON embedding_cache(payload_hash);
    CREATE INDEX IF NOT EXISTS idx_last_used ON embedding_cache(last_used_at);
    """

    def __init__(self, db_path: str = ".a2a_mesh/embedding_cache.db"):
        self.db_path = db_path
        os.makedirs(os.path.dirname(db_path), exist_ok=True)
        self._conn: Optional[sqlite3.Connection] = None
        self._connect()

    def _connect(self):
        self._conn = sqlite3.connect(
            self.db_path,
            check_same_thread=False,
        )
        self._conn.row_factory = sqlite3.Row
        self._conn.executescript(self.SCHEMA)
        self._conn.commit()

    def get(self, point_id: str) -> Optional[CachedEmbedding]:
        """Lekér egy cache-elt embeddinget point_id alapján."""
        cursor = self._conn.execute(
            "SELECT * FROM embedding_cache WHERE point_id = ?",
            (point_id,),
        )
        row = cursor.fetchone()
        if row is None:
            return None
        return CachedEmbedding(
            point_id=row["point_id"],
            payload_hash=row["payload_hash"],
            vector=json.loads(row["vector_json"]),
            payload=json.loads(row["payload_json"]),
            created_at=row["created_at"],
            last_used_at=row["last_used_at"],
            access_count=row["access_count"],
        )

    def put(
        self,
        point_id: str,
        payload_hash: str,
        vector: List[float],
        payload: Dict[str, Any],
    ) -> None:
        """Beszúr vagy frissít egy cache bejegyzést."""
        now = time.time()
        self._conn.execute(
            """
            INSERT INTO embedding_cache
                (point_id, payload_hash, vector_json, payload_json,
                 created_at, last_used_at, access_count)
            VALUES (?, ?, ?, ?, ?, ?, 0)
            ON CONFLICT(point_id) DO UPDATE SET
                payload_hash = excluded.payload_hash,
                vector_json = excluded.vector_json,
                payload_json = excluded.payload_json,
                created_at = excluded.created_at,
                last_used_at = excluded.last_used_at,
                access_count = 0
            """,
            (
                point_id,
                payload_hash,
                json.dumps(vector, ensure_ascii=False),
                json.dumps(payload, ensure_ascii=False, default=str),
                now,
                now,
            ),
        )
        self._conn.commit()

    def touch(self, point_id: str) -> None:
        """Frissíti a last_used_at és access_count mezőket (cache hit esetén)."""
        now = time.time()
        self._conn.execute(
            """
            UPDATE embedding_cache
            SET last_used_at = ?, access_count = access_count + 1
            WHERE point_id = ?
            """,
            (now, point_id),
        )
        self._conn.commit()

    def delete(self, point_id: str) -> None:
        """Töröl egy cache bejegyzést."""
        self._conn.execute(
            "DELETE FROM embedding_cache WHERE point_id = ?",
            (point_id,),
        )
        self._conn.commit()

    def get_stats(self) -> Dict[str, Any]:
        """Statisztikák a cache-ről."""
        cursor = self._conn.execute(
            "SELECT COUNT(*) as cnt, "
            "SUM(access_count) as total_access, "
            "MIN(created_at) as oldest, "
            "MAX(last_used_at) as newest "
            "FROM embedding_cache"
        )
        row = cursor.fetchone()
        return {
            "total_entries": row["cnt"] or 0,
            "total_access_count": row["total_access"] or 0,
            "oldest_entry": row["oldest"],
            "newest_entry": row["newest"],
        }

    def cleanup_old_entries(self, max_age_seconds: float = 86400 * 30) -> int:
        """Törli a régi, nem használt bejegyzéseket. Visszatér a törölt sorok számával."""
        cutoff = time.time() - max_age_seconds
        cursor = self._conn.execute(
            "DELETE FROM embedding_cache WHERE last_used_at < ?",
            (cutoff,),
        )
        self._conn.commit()
        return cursor.rowcount

    def close(self):
        if self._conn:
            self._conn.close()
            self._conn = None


# ---------------------------------------------------------------------------
# Mock Qdrant client (demo célra)
# ---------------------------------------------------------------------------

class MockQdrantClient:
    """
    Mock Qdrant kliens, amely memóriában tárolja a pontokat.
    A valódi implementációban a qdrant_client.QdrantClient helyettesíti.
    """

    def __init__(self):
        self._points: Dict[str, Dict[str, Any]] = {}

    def upsert(self, collection_name: str, points: List[Dict[str, Any]]) -> None:
        for p in points:
            self._points[p["id"]] = p

    def get_point(self, point_id: str) -> Optional[Dict[str, Any]]:
        return self._points.get(point_id)

    def count_points(self) -> int:
        return len(self._points)

    def list_points(self) -> List[Dict[str, Any]]:
        return list(self._points.values())


# ---------------------------------------------------------------------------
# Embedding szinkronizáló
# ---------------------------------------------------------------------------

class EmbeddingSyncManager:
    """
    Kezeli a Qdrant szinkronizációt embedding cache-sel.
    Csak akkor számol új vektort, ha a payload megváltozott.
    """

    def __init__(
        self,
        cache: EmbeddingCache,
        qdrant_client: Any,
        embedding_fn: Callable[[Dict[str, Any]], List[float]],
        collection_name: str = "a2a_mesh_messages",
    ):
        self.cache = cache
        self.qdrant = qdrant_client
        self.embedding_fn = embedding_fn
        self.collection_name = collection_name

    def sync_point(
        self,
        point_id: str,
        payload: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Szinkronizál egyetlen pontot a Qdrant-be.
        Visszatér a művelet részleteivel.
        """
        payload_hash = compute_payload_hash(payload)
        cached = self.cache.get(point_id)

        if cached is not None and cached.payload_hash == payload_hash:
            # Cache hit — payload nem változott, újrahasználjuk a vektort
            self.cache.touch(point_id)
            vector = cached.vector
            action = "cached"
        else:
            # Cache miss vagy payload változott — új embedding számítása
            try:
                vector = self.embedding_fn(payload)
                self.cache.put(point_id, payload_hash, vector, payload)
                action = "new" if cached is None else "updated"
            except Exception as e:
                return {
                    "point_id": point_id,
                    "action": "error",
                    "error": str(e),
                }

        # Qdrant upsert
        point = {
            "id": point_id,
            "vector": vector,
            "payload": payload,
        }
        self.qdrant.upsert(self.collection_name, [point])

        return {
            "point_id": point_id,
            "action": action,
            "payload_hash": payload_hash[:16] + "...",
            "vector_dim": len(vector),
        }

    def sync_batch(
        self,
        items: List[Tuple[str, Dict[str, Any]]],
    ) -> SyncResult:
        """
        Szinkronizál egy batch pontot. Visszatér a SyncResult-tal.
        """
        start = time.time()
        result = SyncResult(total_points=len(items))

        for point_id, payload in items:
            detail = self.sync_point(point_id, payload)
            result.details.append(detail)

            if detail["action"] == "cached":
                result.cached_embeddings += 1
            elif detail["action"] in ("new", "updated"):
                result.new_embeddings += 1
            elif detail["action"] == "error":
                result.errors += 1

        result.elapsed_seconds = time.time() - start
        return result

    def sync_with_dedup(
        self,
        items: List[Tuple[str, Dict[str, Any]]],
    ) -> SyncResult:
        """
        Szinkronizál deduplikációval: ha több azonos point_id van,
        csak az utolsó payload-t használja.
        """
        deduped: Dict[str, Dict[str, Any]] = {}
        for point_id, payload in items:
            deduped[point_id] = payload
        unique_items = list(deduped.items())
        return self.sync_batch(unique_items)


# ---------------------------------------------------------------------------
# Demo embedding függvény (szimulált, de determinisztikus)
# ---------------------------------------------------------------------------

def demo_embedding_fn(payload: Dict[str, Any]) -> List[float]:
    """
    Determinisztikus 'embedding' függvény demo célra.
    A valódi implementációban ez egy LLM/API hívás lenne.
    Szimuláljuk a számítási költséget egy sleep-pel.
    """
    # Szimulált számítási idő (50ms)
    time.sleep(0.05)

    # Determinisztikus vektor a payload hash-ből
    payload_str = json.dumps(payload, sort_keys=True, ensure_ascii=False, default=str)
    hash_bytes = hashlib.sha256(payload_str.encode("utf-8")).digest()

    # 128-dimenziós vektor
    vector = []
    for i in range(128):
        byte_idx = i % len(hash_bytes)
        # -1 és 1 közötti érték
        val = (hash_bytes[byte_idx] / 127.5) - 1.0
        vector.append(round(val, 6))

    return vector


